#!/usr/bin/env python3
# Some portions generated by Codex.
import pathlib,json
p=pathlib.Path(__file__).resolve().parent;s=json.loads((p/'summary.json').read_text());q=json.loads((p/'qualification-summary.json').read_text())
o=['# Qualified stack across an in-memory HTTP workload range','','Compare only original experimental base `5ac89b5` against qualified depth+typed-serializer stack `d94617b3`. No ordered adapter, holder, initializer-restoration, cancellation or memo test seam. This is not current upstream main and not a merge-readiness certification.','','## Outcome by workload','','The benefit is workload-dependent. Reference100k six-slot completion improved8.36%, all pairs favorable with a descriptive95% interval excluding zero. Small10k six-slot completion showed no gain. Wide100k thirty-slot completion was2.76% slower pooled with mostly adverse signs, but uncertainty crosses zero. Large250k six-slot completion was14.29% lower, all pairs favorable but one nearly flat and its interval narrowly crosses zero. No workload established a first-rows-batch latency improvement. Do not claim a universal speedup or merge readiness.','','All32 forks and2,560 requests completed with no excluded workload, no changed cap, no spills and no failed route/cleanup check.640 requests were measured; eight separate full-term qualifications also passed.','','## Scope and fixed protocol','','Actual on-disk LMDB with synthetic RDF, Server binary writer/HTTP, Workbench Java decoder and NDJSON writer, Node streaming decode/count. Browser rendering and concurrent QPS are excluded. Four paired fresh-server blocks per workload (AB/BA/AB/BA), 60 warmups + 20 measured requests; all samples retained. Each server receives a fresh clone of its frozen fixture. Same640 MiB per-query/2.5 GiB global budget and common JDK/heap/flags.','','First row means the first complete NDJSON rows record parsed by Node, normally first32 rows, not first engine tuple or browser paint. EOF includes client parsing/backpressure. Readiness waits for overlay/adjacency; first application query is not cold storage. Per-workload paired-log t intervals use4 independent fork pairs, are descriptive/unadjusted and not corrected for multiple comparisons. No pooled overall speedup across unlike shapes.','','## Qualification','','All8 cells passed exact every-term validation, unique Cartesian-product bag proof, independently enumerated dual checksums, complete count/status, class origins, compiled route, no spill/migration and ledger cleanup. Wide30 has identical WHERE body to reference6; it projects24 extra functionally determined attributes including null OPTIONAL suffixes. Formula oracle and full observed diagnostics are retained.','','| Shape | Rows | Slots | Base/stack charged qualification peak bytes |','|---|---:|---:|---|']
for shape,x in q.items():o.append(f"| {shape} | {x['base']['rows']} | {30 if shape=='wide30' else 6} | {x['base']['peak']} / {x['stack']['peak']} |")
o+=['','These are process-lifetime query-ledger peaks observed after one qualification query, not total memory/RSS. All qualified shapes retain the fixed cap; none was excluded or silently altered.','','## Per-workload results','']
for shape,v in s.items():
 o+=['### '+shape,'']
 if v['status']!='complete':o+=['Pending complete paired series.',''];continue
 a,b=v['arms']['base'],v['arms']['stack'];o+=['| Metric | Base ms | Stack ms | Reduction % | Paired reductions % | Descriptive95% interval % |','|---|---:|---:|---:|---|---|']
 for k in ['eofMs','firstRowMs']:
  c=v['contrasts'][k];o.append(f"| {k} | {a['means'][k]:.3f} | {b['means'][k]:.3f} | {c['latencyReductionPercent']:.2f} | {', '.join(f'{x:+.2f}' for x in c['pairedReductionPercent'])} | {c['descriptive95ReductionInterval'][0]:+.2f} to {c['descriptive95ReductionInterval'][1]:+.2f} |")
 c=v['contrasts']['eofMs'];o += ['',f"Derived sequential rows/s change: {c['derivedThroughputChangePercent']:+.2f}%. This is not concurrent capacity.",'','| Fork | Arm | EOF ms | First rows-batch ms |','|---|---|---:|---:|']
 for f in v['forks']:o.append(f"| {f['name']} | {f['arm']} | {f['means']['eofMs']:.3f} | {f['means']['firstRowMs']:.3f} |")
 o+=['','Measured EOF segments (first7/middle6/last7):']
 for arm in ['base','stack']:o.append('- '+arm+': '+', '.join(f'{x:.3f} ms' for x in v['arms'][arm]['eofSegments']))
 o+=['','Per-request Janino compilation/cache/instantiation and DISTINCT/memo counters remain in summary.json and raw outputs. A compiled route is not proof of byte-identical generated plans or JIT code across forks.','']
o+=['## Limitations and evidence','','Fixed warmup does not guarantee convergence; preserve segment trends rather than select a favorable suffix. Four forks per arm limit precision. Timing counts/route checks run on every request; computationally expensive complete-term/oracle checks are untimed qualification. Whole-JVM GC logs cannot be attributed to individual queries; heap snapshots are not allocation. RSS was not measured. No new profiles were run in this range phase.','','Raw request metrics/logs remain local and are published via lossless exact-byte pool dedup with SHA256 reconstruction verification. Source/runtime/fixture manifests, independent formula oracle, qualification diagnostics and reviewer notes define the reproducible scope.','']
(p/'RESULTS.md').write_text('\n'.join(o).replace('Same640','Same 640').replace('first32','first 32').replace('use4','use 4').replace('All8','All 8').replace('projects24','projects 24').replace('Descriptive95','Descriptive 95').replace('first7/middle6/last7','first 7/middle 6/last 7').replace('Reference100k','Reference 100k').replace('improved8.36','improved 8.36').replace('descriptive95','descriptive 95').replace('Small10k','Small 10k').replace('Wide100k','Wide 100k').replace('was2.76','was 2.76').replace('Large250k','Large 250k').replace('was14.29','was 14.29').replace('All32','All 32').replace('and2,560','and 2,560').replace('check.640','check. 640'))

with (p/'RESULTS.md').open('a') as f:
 f.write('\n## Measured route/cache stability\n\nFor every measured query in every arm/workload: zero Janino compilations and cache misses; one cache hit, one grouped tracker and one budgeted-wide admission; zero spill creation/migration and object rows. Primitive-row deltas equal the workload row count. Both-arm matching is observed per request, not inferred from flags. No observed route/cache drift explains the timing differences, but this is not full generated-plan/JIT identity proof.\n\nFrozen protocol/source/class/fixture manifests and published-setup.json connect this evidence to the prior setup checkpoint. Existing safety qualification is documented in read-depth/broad-safety and compact-json reports; this range run adds workload validation, not a full repository or release certification.\n')
